class Solution {
  public int minimumOR(int[][] grid) {
    int allowed = (1 << 17) - 1;
    for (int bit = 16; bit >= 0; bit--) {
      int candidate = allowed & ~(1 << bit);
      boolean ok = true;
      for (int[] row : grid) {
        boolean found = false;
        for (int x : row) {
          if ((x & ~candidate) == 0) {
            found = true;
            break;
          }
        }
        if (!found) {
          ok = false;
          break;
        }
      }
      if (ok) allowed = candidate;
    }
    return allowed;
  }
}
